import React, { useEffect, useMemo, useRef, useState } from "react";
import { AccessibilityInfo, PanResponder, View, type ViewStyle } from "react-native";
import { Canvas, Fill, Shader, Skia } from "@shopify/react-native-skia";
import { useDerivedValue, useFrameCallback, useSharedValue } from "react-native-reanimated";
import {
  REVEAL_DEFAULTS,
  brushDown,
  brushMove,
  brushPresetPatch,
  brushRelease,
  brushStep,
  createBrush,
  type RevealBrush,
  type RevealPointer,
} from "./revealMath";
import { REVEAL_BACKGROUND, REVEAL_H, REVEAL_STAMPS, REVEAL_W } from "./revealDesign";
import { REVEAL_SHADER } from "./revealShader";

export type CodeRevealProps = {
  colorGlyphs?: boolean;
  slowMotion?: boolean;
  reducedMotion?: boolean;
  onFeedback?: (event: "touch" | "release") => void;
  label?: string;
  style?: ViewStyle;
};

const SKSL = `${REVEAL_SHADER}
half4 main(float2 p) {
  return half4(half3(codeRevealColor(p)), 1.0);
}
`;

let cachedEffect: ReturnType<typeof Skia.RuntimeEffect.Make> | undefined;
function getEffect() {
  if (cachedEffect === undefined) cachedEffect = Skia.RuntimeEffect.Make(SKSL);
  return cachedEffect;
}

function CanvasKeepAlive() {
  const [beat, setBeat] = useState(0);
  useEffect(() => {
    let cancelled = false;
    const tick = () => {
      if (cancelled) return;
      setBeat((b) => b + 1);
      requestAnimationFrame(tick);
    };
    const id = requestAnimationFrame(tick);
    return () => {
      cancelled = true;
      cancelAnimationFrame(id);
    };
  }, []);
  return (
    <View
      pointerEvents="none"
      style={{ position: "absolute", width: 1, height: 1, opacity: 0, transform: [{ translateX: beat % 2 }] }}
    />
  );
}

export function CodeReveal({
  colorGlyphs = false,
  slowMotion = false,
  reducedMotion,
  onFeedback,
  label = "Image that turns into glyphs under your finger",
  style,
}: CodeRevealProps) {
  const [systemReduce, setSystemReduce] = useState(false);
  const reduce = reducedMotion ?? systemReduce;
  const opts = useMemo(() => REVEAL_DEFAULTS, []);
  const effect = useMemo(() => getEffect(), []);
  const brush = useSharedValue<RevealBrush>(createBrush(opts));
  const frame = useSharedValue(0);
  const pointer = useSharedValue<RevealPointer>({ x: 0, y: 0, down: 0, seq: 0 });
  const slowM = useSharedValue(false);
  const colorM = useSharedValue(false);
  const reduceM = useSharedValue(false);
  const latest = useRef({ reduce, onFeedback, seq: 0 });
  latest.current.reduce = reduce;
  latest.current.onFeedback = onFeedback;

  useEffect(() => {
    let alive = true;
    AccessibilityInfo.isReduceMotionEnabled()
      .then((v) => {
        if (alive) setSystemReduce(v);
      })
      .catch(() => {});
    const sub = AccessibilityInfo.addEventListener("reduceMotionChanged", setSystemReduce);
    return () => {
      alive = false;
      sub.remove();
    };
  }, []);
  useEffect(() => {
    slowM.value = slowMotion;
  }, [slowMotion, slowM]);
  useEffect(() => {
    colorM.value = colorGlyphs;
    frame.value = frame.value + 1;
  }, [colorGlyphs, colorM, frame]);
  useEffect(() => {
    reduceM.value = reduce;
    const fresh = createBrush(opts);
    if (reduce) brushPresetPatch(fresh, REVEAL_W * 0.5, REVEAL_H * 0.55, 80, opts);
    brush.value = fresh;
    frame.value = frame.value + 1;
  }, [reduce, reduceM, brush, frame, opts]);

  const pan = useMemo(() => {
    const send = (x: number, y: number, down: number) => {
      latest.current.seq += 1;
      pointer.value = { x, y, down, seq: latest.current.seq };
    };
    return PanResponder.create({
        onStartShouldSetPanResponder: () => !latest.current.reduce,
        onPanResponderGrant: (evt) => {
          send(evt.nativeEvent.locationX, evt.nativeEvent.locationY, 1);
          latest.current.onFeedback?.("touch");
        },
        onPanResponderMove: (evt) => {
          send(evt.nativeEvent.locationX, evt.nativeEvent.locationY, 1);
        },
        onPanResponderRelease: () => {
          send(pointer.value.x, pointer.value.y, 0);
          latest.current.onFeedback?.("release");
        },
        onPanResponderTerminate: () => {
          send(pointer.value.x, pointer.value.y, 0);
        },
        onPanResponderTerminationRequest: () => false,
    });
  }, [pointer]);

  useFrameCallback((info) => {
    if (reduceM.value) return;
    const b = brush.value;
    const p = pointer.value;
    if (p.seq !== b.seq) {
      if (p.down && !b.down) brushDown(b, p.x, p.y, info.timestamp, opts);
      else if (p.down) brushMove(b, p.x, p.y, info.timestamp, opts);
      else brushRelease(b);
      b.seq = p.seq;
    }
    const dt = Math.min(48, info.timeSincePreviousFrame ?? 16.7) / 1000;
    brushStep(b, dt * (slowM.value ? 0.25 : 1), opts);
    frame.value = frame.value + 1;
  });

  const uniforms = useDerivedValue(() => {
    frame.value;
    const d = brush.value.data;
    const u: Record<string, number | number[]> = { size: [REVEAL_W, REVEAL_H], mode: colorM.value ? 1 : 0 };
    for (let i = 0; i < REVEAL_STAMPS; i++) u["s" + i] = [d[i * 4], d[i * 4 + 1], d[i * 4 + 2], d[i * 4 + 3]];
    return u;
  });

  return (
    <View
      style={[{ width: REVEAL_W, height: REVEAL_H, borderRadius: 18, overflow: "hidden", backgroundColor: REVEAL_BACKGROUND }, style]}
      accessibilityLabel={label}
      accessibilityRole="image"
      {...pan.panHandlers}
    >
      {!reduce ? <CanvasKeepAlive /> : null}
      <Canvas pointerEvents="none" style={{ width: REVEAL_W, height: REVEAL_H }}>
        <Fill color={REVEAL_BACKGROUND} />
        {effect ? (
          <Fill>
            <Shader source={effect} uniforms={uniforms} />
          </Fill>
        ) : null}
      </Canvas>
    </View>
  );
}

export const REVEAL_DEFAULTS = {
  slots: 40,
  minRadius: 26,
  maxRadius: 64,
  speedScale: 700,
  speedSmoothing: 0.4,
  spacing: 0.28,
  maxPerMove: 10,
  tau: 0.7,
  cutoff: 0.004,
};

export type RevealOptions = typeof REVEAL_DEFAULTS;

export type RevealBrush = {
  data: number[];
  head: number;
  x: number;
  y: number;
  t: number;
  speed: number;
  radius: number;
  down: number;
  seq: number;
};

export type RevealPointer = { x: number; y: number; down: number; seq: number };

export function createBrush(opts: RevealOptions): RevealBrush {
  "worklet";
  return {
    data: new Array(opts.slots * 4).fill(0),
    head: 0,
    x: 0,
    y: 0,
    t: 0,
    speed: 0,
    radius: opts.minRadius,
    down: 0,
    seq: 0,
  };
}

export function brushRadius(speed: number, opts: RevealOptions): number {
  "worklet";
  return opts.minRadius + (opts.maxRadius - opts.minRadius) * (1 - Math.exp(-speed / opts.speedScale));
}

function writeStamp(b: RevealBrush, slot: number, x: number, y: number, r: number, s: number) {
  "worklet";
  const i = slot * 4;
  b.data[i] = x;
  b.data[i + 1] = y;
  b.data[i + 2] = r;
  b.data[i + 3] = s;
}

function pushStamp(b: RevealBrush, x: number, y: number, r: number, opts: RevealOptions) {
  "worklet";
  writeStamp(b, b.head, x, y, r, 1);
  b.head = (b.head + 1) % (opts.slots - 1);
}

export function brushDown(b: RevealBrush, x: number, y: number, t: number, opts: RevealOptions) {
  "worklet";
  b.x = x;
  b.y = y;
  b.t = t;
  b.speed = 0;
  b.radius = brushRadius(0, opts);
  b.down = 1;
  writeStamp(b, opts.slots - 1, x, y, b.radius, 1);
}

export function brushMove(b: RevealBrush, x: number, y: number, t: number, opts: RevealOptions) {
  "worklet";
  const dx = x - b.x;
  const dy = y - b.y;
  const dist = Math.hypot(dx, dy);
  const dt = Math.max(1, t - b.t) / 1000;
  b.speed += (dist / dt - b.speed) * opts.speedSmoothing;
  const r1 = brushRadius(b.speed, opts);
  const r0 = b.radius;
  const n = Math.min(opts.maxPerMove, Math.max(1, Math.ceil(dist / (Math.max(r0, r1) * opts.spacing))));
  for (let k = 1; k <= n; k++) {
    const f = k / n;
    pushStamp(b, b.x + dx * f, b.y + dy * f, r0 + (r1 - r0) * f, opts);
  }
  b.x = x;
  b.y = y;
  b.t = t;
  b.radius = r1;
  b.down = 1;
  writeStamp(b, opts.slots - 1, x, y, r1, 1);
}

export function brushRelease(b: RevealBrush) {
  "worklet";
  b.down = 0;
  b.speed = 0;
}

export function brushStep(b: RevealBrush, dt: number, opts: RevealOptions): boolean {
  "worklet";
  const f = Math.exp(-Math.max(0, dt) / opts.tau);
  let active = false;
  const last = opts.slots - 1;
  for (let k = 0; k < opts.slots; k++) {
    const i = k * 4 + 3;
    if (k === last && b.down) {
      b.data[i] = 1;
      active = true;
      continue;
    }
    let s = b.data[i] * f;
    if (s < opts.cutoff) s = 0;
    b.data[i] = s;
    if (s > 0) active = true;
  }
  return active;
}

export function brushActive(b: RevealBrush): boolean {
  "worklet";
  for (let k = 3; k < b.data.length; k += 4) if (b.data[k] > 0) return true;
  return false;
}

export function brushPresetPatch(b: RevealBrush, x: number, y: number, r: number, opts: RevealOptions) {
  "worklet";
  writeStamp(b, 0, x, y, r, 1);
  b.head = 1 % (opts.slots - 1);
}

export const REVEAL_SHADER = `
uniform float2 size;
uniform float mode;
${Array.from({ length: 40 }, (_, i) => `uniform float4 s${i};`).join("\n")}

const float CELL = 9.0;

float hash21(float2 p) {
  return fract(sin(dot(p, float2(127.1, 311.7))) * 43758.5453);
}

float vnoise(float2 p) {
  float2 i = floor(p);
  float2 f = fract(p);
  f = f * f * (3.0 - 2.0 * f);
  float a = hash21(i);
  float b = hash21(i + float2(1.0, 0.0));
  float c = hash21(i + float2(0.0, 1.0));
  float d = hash21(i + float2(1.0, 1.0));
  return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}

float ridgeLine(float x, float seed, float freq, float amp, float base) {
  float n = vnoise(float2(x * freq + seed, seed)) * 0.65 + vnoise(float2(x * freq * 2.3 + seed * 1.7, seed * 3.0)) * 0.35;
  return base - amp * n;
}

float3 layer(float3 col, float py, float y, float yref, float3 top, float3 bottom, float depth) {
  float m = smoothstep(-1.2, 1.2, py - y);
  float k = clamp((py - yref) / depth, 0.0, 1.0);
  float3 body = mix(top, bottom, k);
  body = mix(body, float3(1.0, 0.75, 0.7), 0.3 * (1.0 - smoothstep(0.0, 3.0, py - y)));
  return mix(col, body, m);
}

float3 scene(float2 p) {
  float H = size.y;
  float t = clamp(p.y / (0.64 * H), 0.0, 1.0);
  float3 col = mix(float3(0.10, 0.05, 0.30), float3(0.92, 0.22, 0.52), smoothstep(0.0, 0.62, t));
  col = mix(col, float3(1.0, 0.66, 0.22), smoothstep(0.55, 1.0, t));
  float2 sf = fract(p / 7.0) - 0.5;
  float star = step(0.987, hash21(floor(p / 7.0))) * (1.0 - smoothstep(0.0, 0.4, t)) * (1.0 - smoothstep(0.1, 0.24, length(sf)));
  col += float3(0.8, 0.8, 0.9) * star;
  float2 sc = float2(0.5 * size.x, 0.45 * H);
  float R = 0.19 * size.x;
  float d = length(p - sc);
  col += float3(1.0, 0.4, 0.3) * 0.35 * exp(-d / (R * 1.8));
  float disc = 1.0 - smoothstep(R - 1.2, R + 1.2, d);
  float bi = (p.y - sc.y) / R;
  float keep = bi > 0.1 ? step(fract(bi * 6.0), 0.85 - 0.6 * bi) : 1.0;
  float3 sun = mix(float3(1.0, 0.93, 0.45), float3(1.0, 0.35, 0.55), clamp((p.y - (sc.y - R)) / (2.0 * R), 0.0, 1.0));
  col = mix(col, sun, disc * keep);
  float y1 = ridgeLine(p.x, 1.0, 0.012, 0.13 * H, 0.60 * H);
  float y2 = ridgeLine(p.x, 7.0, 0.016, 0.12 * H, 0.69 * H);
  float y3 = ridgeLine(p.x, 13.0, 0.022, 0.10 * H, 0.80 * H);
  col = layer(col, p.y, y1, 0.52 * H, float3(0.78, 0.30, 0.50), float3(0.30, 0.10, 0.42), 0.22 * H);
  col = layer(col, p.y, y2, 0.60 * H, float3(0.42, 0.16, 0.50), float3(0.14, 0.06, 0.30), 0.22 * H);
  col = layer(col, p.y, y3, 0.72 * H, float3(0.20, 0.08, 0.34), float3(0.05, 0.02, 0.14), 0.28 * H);
  return col;
}

float bar(float2 q, float hx, float hy) {
  float2 d = abs(q) - float2(hx, hy);
  return 1.0 - smoothstep(-0.05, 0.05, max(d.x, d.y));
}

float glyph(float k, float2 q) {
  if (k < 0.5) return 0.0;
  if (k < 1.5) return 1.0 - smoothstep(0.07, 0.14, length(q));
  if (k < 2.5) {
    float a = 1.0 - smoothstep(0.06, 0.12, length(q - float2(0.0, -0.18)));
    float b = 1.0 - smoothstep(0.06, 0.12, length(q - float2(0.0, 0.18)));
    return max(a, b);
  }
  if (k < 3.5) return bar(q, 0.26, 0.055);
  if (k < 4.5) return max(bar(q - float2(0.0, -0.13), 0.26, 0.05), bar(q - float2(0.0, 0.13), 0.26, 0.05));
  float plus = max(bar(q, 0.27, 0.055), bar(q, 0.055, 0.27));
  float a = abs(q.x - q.y) * 0.7071;
  float b = abs(q.x + q.y) * 0.7071;
  float xg = bar(q, 0.3, 0.3) * (1.0 - smoothstep(0.04, 0.1, min(a, b)));
  if (k < 5.5) return plus;
  if (k < 6.5) return xg;
  if (k < 7.5) return max(plus, xg);
  if (k < 8.5) {
    float v = max(bar(q - float2(-0.12, 0.0), 0.045, 0.3), bar(q - float2(0.12, 0.0), 0.045, 0.3));
    float h = max(bar(q - float2(0.0, -0.12), 0.3, 0.045), bar(q - float2(0.0, 0.12), 0.3, 0.045));
    return max(v, h);
  }
  float ring = 1.0 - smoothstep(0.0, 0.06, abs(length(q) - 0.3) - 0.07);
  float dot0 = 1.0 - smoothstep(0.12, 0.18, length(q));
  return max(ring, dot0);
}

float stampAt(float4 s, float2 q) {
  if (s.w <= 0.0) return 0.0;
  return (1.0 - smoothstep(0.3, 1.0, length(q - s.xy) / s.z)) * s.w;
}

float3 codeRevealColor(float2 p) {
  float rp = 0.0;
  float2 cc = floor(p / CELL) * CELL + CELL * 0.5;
  float rc = 0.0;
${Array.from({ length: 40 }, (_, i) => `  rp = max(rp, stampAt(s${i}, p));\n  rc = max(rc, stampAt(s${i}, cc));`).join("\n")}
  float3 img = scene(p);
  if (rp <= 0.002) return img;
  float h = CELL * 0.25;
  float3 c0 = scene(cc + float2(-h, -h));
  float3 c1 = scene(cc + float2(h, -h));
  float3 c2 = scene(cc + float2(-h, h));
  float3 c3 = scene(cc + float2(h, h));
  float3 avg = (c0 + c1 + c2 + c3) * 0.25;
  float L = dot(avg, float3(0.3, 0.59, 0.11));
  float dens = clamp(L * 1.2, 0.0, 1.0) * (0.3 + 0.7 * smoothstep(0.0, 0.8, rc));
  float k = clamp(floor(dens * 9.0 + 0.0001), 0.0, 9.0);
  float2 q = (p - (cc - CELL * 0.5)) / CELL - 0.5;
  float ink = glyph(k, q);
  float m = max(avg.r, max(avg.g, avg.b));
  float3 tint = avg / max(m, 0.05) * (0.55 + 0.45 * m);
  float3 inkCol = mode > 0.5 ? tint : float3(0.97, 0.95, 0.9);
  float3 layerCol = mix(float3(0.03, 0.035, 0.05), inkCol, ink);
  return mix(img, layerCol, smoothstep(0.0, 0.5, rp));
}
`;

export const REVEAL_W = 320;
export const REVEAL_H = 340;
export const REVEAL_CELL = 9;
export const REVEAL_STAMPS = 40;
export const REVEAL_BACKGROUND = "#0d0a1f";

import React, { useState } from "react";
import { Pressable, Text, View } from "react-native";
import { CodeReveal } from "./CodeReveal";

export default function Example({ onFeedback }: { onFeedback?: (event: "touch" | "release") => void }) {
  const [color, setColor] = useState(false);
  const [slow, setSlow] = useState(false);
  const chip = (on: boolean) => ({
    paddingVertical: 9, paddingHorizontal: 13, borderRadius: 24, borderWidth: 1,
    backgroundColor: on ? "#315843" : "#eeeade", borderColor: on ? "#315843" : "#c7caba",
  });
  return (
    <View style={{ alignItems: "center", gap: 10, paddingVertical: 14 }}>
      <CodeReveal colorGlyphs={color} slowMotion={slow} onFeedback={onFeedback} />
      <View style={{ flexDirection: "row", gap: 8 }}>
        <Pressable accessibilityRole="switch" accessibilityState={{ checked: color }} onPress={() => setColor((v) => !v)} style={chip(color)}>
          <Text style={{ fontSize: 12, color: color ? "#fff" : "#315843", fontFamily: "Geist-Regular" }}>Color glyphs: {color ? "on" : "off"}</Text>
        </Pressable>
        <Pressable accessibilityRole="switch" accessibilityState={{ checked: slow }} onPress={() => setSlow((v) => !v)} style={chip(slow)}>
          <Text style={{ fontSize: 12, color: slow ? "#fff" : "#315843", fontFamily: "Geist-Regular" }}>Slow motion: {slow ? "on" : "off"}</Text>
        </Pressable>
      </View>
      <Text style={{ fontSize: 12, color: "#63705f", fontFamily: "Geist-Regular" }}>Drag a finger across the picture. Move faster for a bigger brush.</Text>
    </View>
  );
}
